#!/usr/bin/env bash
# PR gate for ClassHub (docs/DEVELOPMENT.md "Independent Codex review").
# Inputs (environment): GH_TOKEN, REPO, PR_NUMBER, HEAD_REF, HEAD_SHA (the commit this check certifies),
# optional PR_BODY (fallback when the API is unavailable), optional EVIDENCE_PUBLIC_KEY (defaults to the
# trusted public key next to this script, which the workflow checks out from the base branch).
#
# The Codex evidence block is generated by `node scripts/codex-review.mjs` from the real transcript. The
# gate checks that it is complete, internally consistent, and certifies exactly HEAD_SHA:
#   - allowed branch name
#   - "Codex review: completed", full 40-char "Reviewed commit" equal to HEAD_SHA, full "Base commit"
#   - "Codex CLI" version and a 64-hex "Transcript SHA-256"
#   - the declared final-round severity counts equal the counts recomputed from the raw Codex output
#   - unresolved critical/high (P0+P1 minus documented rejections) is 0; rejections need a
#     "### Rejected findings" section with reasoning
#   - the evidence carries a valid Ed25519 signature from the evidence key (scripts/ci/evidence-signature.mjs):
#     evidence typed by hand or edited after signing fails
set -euo pipefail

fail() {
  echo "::error::$1"
  exit 1
}

# Every evidence field is read from the single marked evidence block only (the same text the signature
# covers), never from elsewhere in the body: lines outside the block cannot change what is checked.
field() { (grep -E "^$1: " <<<"$block" || true) | head -n1 | sed -E "s|^$1: ||" | tr -d '[:space:]'; }

# Read the current PR body from the API: a re-run reuses the original event payload, which may hold an
# outdated body. Fall back to the event's body only if the API is unavailable.
body="$(gh api "repos/$REPO/pulls/$PR_NUMBER" --jq '.body // ""' 2>/dev/null || printf '%s' "${PR_BODY:-}")"
body="${body//$'\r'/}"

# 1. Branch naming: feature/*, fix/*, chore/* (Dependabot branches are allowed but still need a review).
if [[ ! "$HEAD_REF" =~ ^(feature|fix|chore)/[a-z0-9][a-z0-9._-]*$ && ! "$HEAD_REF" =~ ^dependabot/ ]]; then
  fail "Branch '$HEAD_REF' must match feature/*, fix/* or chore/* (lowercase)."
fi

hint="Generate it with 'node scripts/codex-review.mjs review' and 'node scripts/codex-review.mjs apply --pr $PR_NUMBER --evidence <file>' (see docs/DEVELOPMENT.md)."

# 2. Evidence block.
grep -q '<!-- codex-review:start -->' <<<"$body" && grep -q '<!-- codex-review:end -->' <<<"$body" \
  || fail "No generated Codex evidence block (codex-review:start/end markers). $hint"
starts="$(grep -c '<!-- codex-review:start -->' <<<"$body" || true)"
ends="$(grep -c '<!-- codex-review:end -->' <<<"$body" || true)"
(( starts == 1 && ends == 1 )) || fail "The body must contain exactly one Codex evidence block (found $starts start and $ends end markers). $hint"
block="$(awk '/<!-- codex-review:start -->/{f=1} f{print} /<!-- codex-review:end -->/{if(f)exit}' <<<"$body")"
grep -Eq '^Codex review: completed[[:space:]]*$' <<<"$block" || fail "Evidence must state 'Codex review: completed'. $hint"

reviewed="$(field 'Reviewed commit')"
base="$(field 'Base commit')"
cli="$( (grep -E '^Codex CLI: ' <<<"$block" || true) | head -n1 | sed -E 's/^Codex CLI: //')"
transcript="$(field 'Transcript SHA-256')"
[[ "$reviewed" =~ ^[0-9a-f]{40}$ ]] || fail "'Reviewed commit' must be a full 40-character SHA. $hint"
[[ "$base" =~ ^[0-9a-f]{40}$ ]] || fail "'Base commit' must be a full 40-character SHA. $hint"
[[ "$cli" =~ ^codex-cli\ [0-9] ]] || fail "'Codex CLI' must name the codex-cli version that ran the review. $hint"
[[ "$transcript" =~ ^[0-9a-f]{64}$ ]] || fail "'Transcript SHA-256' must be the 64-hex hash of the review transcript. $hint"

# 3. The review certifies exactly the commit this check runs for (re-review after every new commit).
[[ -n "${HEAD_SHA:-}" ]] || fail "HEAD_SHA is not set."
[[ "$reviewed" == "$HEAD_SHA" ]] || fail "The Codex review covers $reviewed, but this check is for $HEAD_SHA. Review the current head and update the evidence. $hint"

# 4. Raw Codex output present; recount severities from it.
raw="$(awk '/<!-- codex-raw-output:start -->/{f=1;next}/<!-- codex-raw-output:end -->/{f=0}f' <<<"$block")"
# Only presence is checked here; whether the review completed is decided semantically by the generator
# (findings or an explicit clean verdict). The shortest real verdict, "No issues found.", has 14 characters.
raw_chars="$(tr -d '[:space:]`' <<<"$raw" | wc -c)"
(( raw_chars >= 10 )) || fail "Raw Codex output is missing between the codex-raw-output markers. $hint"

declared="$( (grep -E '^Final round findings: ' <<<"$block" || true) | head -n1)"
[[ "$declared" =~ ^Final\ round\ findings:\ P0=([0-9]+)\ P1=([0-9]+)\ P2=([0-9]+)\ P3=([0-9]+)[[:space:]]*$ ]] \
  || fail "'Final round findings: P0=n P1=n P2=n P3=n' is missing or malformed. $hint"
d0="${BASH_REMATCH[1]}"; d1="${BASH_REMATCH[2]}"; d2="${BASH_REMATCH[3]}"; d3="${BASH_REMATCH[4]}"

count() { (grep -oE "\[$1\][[:space:]]*.*" <<<"$raw" || true) | sed -E 's/[[:space:]]+/ /g' | cut -c1-124 | sort -u | grep -c . || true; }
c0="$(count P0)"; c1="$(count P1)"; c2="$(count P2)"; c3="$(count P3)"
if [[ "$c0 $c1 $c2 $c3" != "$d0 $d1 $d2 $d3" ]]; then
  fail "Declared findings (P0=$d0 P1=$d1 P2=$d2 P3=$d3) differ from the raw Codex output (P0=$c0 P1=$c1 P2=$c2 P3=$c3)."
fi

# 5. Critical/high findings of the final round are fixed (new round) or rejected with reasoning.
rejected="$(field 'Rejected critical/high')"
unresolved="$(field 'Unresolved critical/high')"
[[ "$rejected" =~ ^[0-9]+$ ]] || fail "'Rejected critical/high: <n>' is missing. $hint"
[[ "$unresolved" =~ ^[0-9]+$ ]] || fail "'Unresolved critical/high: <n>' is missing. $hint"
(( rejected <= d0 + d1 )) || fail "Rejected critical/high ($rejected) exceeds the final round's P0+P1 ($((d0 + d1)))."
(( unresolved == d0 + d1 - rejected )) || fail "Unresolved critical/high must be P0+P1-rejected = $((d0 + d1 - rejected)), not $unresolved."
(( unresolved == 0 )) || fail "There are $unresolved unresolved critical/high Codex findings."
if (( rejected > 0 )); then
  reasoning="$(awk '/^### Rejected findings/{f=1;next}/^#{2,3} /{f=0}f' <<<"$body" | tr -d '[:space:]' | wc -c)"
  (( reasoning >= 80 )) || fail "Rejected critical/high findings need a '### Rejected findings' section with the technical reasoning."
fi

# 6. Signature: only the review script with the private evidence key can produce this evidence.
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
public_key="${EVIDENCE_PUBLIC_KEY:-$here/codex-evidence-public.pem}"
[[ -f "$public_key" ]] || fail "The trusted evidence public key is missing ($public_key)."
body_file="$(mktemp)"
printf '%s' "$body" > "$body_file"
signature_result="$(node "$here/verify-evidence.mjs" "$body_file" "$public_key" "$HEAD_SHA" 2>&1)" || { rm -f "$body_file"; fail "$signature_result $hint"; }
rm -f "$body_file"
echo "$signature_result"

echo "PR gate passed: branch '$HEAD_REF', Codex review of ${reviewed:0:7} (base ${base:0:7}, $cli) recorded, final round P0=$d0 P1=$d1 P2=$d2 P3=$d3, rejected $rejected, unresolved 0."
